CREATE TABLE users (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, target_role VARCHAR(120) DEFAULT 'Software Engineer', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE auth_tokens (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash VARCHAR(64) NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL);CREATE INDEX ix_auth_user ON auth_tokens(user_id);
CREATE TABLE resumes (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,filename VARCHAR(255) NOT NULL,stored_name VARCHAR(255) NOT NULL,extracted_text TEXT NOT NULL,analysis TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX ix_resume_user ON resumes(user_id);
CREATE TABLE interviews (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role VARCHAR(150) NOT NULL,kind VARCHAR(35) NOT NULL,mode VARCHAR(20) NOT NULL,difficulty VARCHAR(20) NOT NULL,experience VARCHAR(30) NOT NULL,proctor_mode VARCHAR(20) NOT NULL,job_description TEXT,question_limit INT NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',current_question TEXT,report TEXT,started_at TIMESTAMPTZ NOT NULL DEFAULT now(),finished_at TIMESTAMPTZ);CREATE INDEX ix_interview_user ON interviews(user_id);
CREATE TABLE answers (id BIGSERIAL PRIMARY KEY, interview_id BIGINT NOT NULL REFERENCES interviews(id) ON DELETE CASCADE, position INT NOT NULL,question TEXT NOT NULL,answer TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(interview_id,position));
CREATE TABLE proctor_events (id BIGSERIAL PRIMARY KEY,interview_id BIGINT NOT NULL REFERENCES interviews(id) ON DELETE CASCADE, category VARCHAR(80) NOT NULL,severity VARCHAR(20) NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),duration_seconds INT,detail VARCHAR(255));CREATE INDEX ix_proctor_session ON proctor_events(interview_id);
CREATE TABLE learning_progress (id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,resource_id VARCHAR(80) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PLANNED',UNIQUE(user_id,resource_id));
